"""End-to-end encrypted Realtime channels: the shared cross-SDK vectors, then the
behaviour built on them (publish seals before the transport, plain channels are
untouched, and every refusal happens client-side)."""

from __future__ import annotations

import base64
import builtins
import json
import pathlib

import httpx
import pytest
import respx

from bird import AsyncBird, Bird, BirdError
from bird._realtime_crypto import (
    decode_master_key,
    derive_shared_secret,
    encrypt_for_channel,
    open_box,
    seal,
)

# Generated by `beak gen:realtime-encryption` from x/crypto's secretbox; every SDK
# test suite replays this file verbatim, which is what pins them to one wire contract.
VECTORS = json.loads(
    (pathlib.Path(__file__).parent / "realtime-encryption-vectors.json").read_text()
)

BASE = "https://eu1.platform.bird.com"
APP = "rap_01krdgeqcxet5s7t44vh8rt9mg"
APP_BASE = f"{BASE}/v1/realtime/apps/{APP}"
MASTER = VECTORS["encrypt"][0]["master_key"]
CHANNEL = "private-encrypted-orders"


def _b64(value: str) -> bytes:
    return base64.b64decode(value)


def client(master_key: str | None = MASTER) -> Bird:
    return Bird(
        api_key="bk_eu1_secret",
        realtime_key="rk_test",
        realtime_secret="rs_test",
        realtime_encryption_master_key=master_key,
    )


def _opened(envelope: dict, channel: str = CHANNEL, master_key: str = MASTER) -> object:
    key = derive_shared_secret(channel, decode_master_key(master_key))
    plain = open_box(_b64(envelope["ciphertext"]), _b64(envelope["nonce"]), key)
    assert plain is not None
    return json.loads(plain)


@pytest.mark.parametrize("vector", VECTORS["derive_shared_secret"], ids=lambda v: v["id"])
def test_derive_shared_secret_matches_the_vector(vector: dict) -> None:
    secret = derive_shared_secret(vector["channel"], decode_master_key(vector["master_key"]))
    assert base64.b64encode(secret).decode() == vector["shared_secret"]


@pytest.mark.parametrize("vector", VECTORS["encrypt"], ids=lambda v: v["id"])
def test_seal_matches_the_vector(vector: dict) -> None:
    key = derive_shared_secret(vector["channel"], decode_master_key(vector["master_key"]))
    box = seal(vector["plaintext"].encode(), _b64(vector["nonce"]), key)
    assert base64.b64encode(box).decode() == vector["ciphertext"]


@pytest.mark.parametrize("vector", VECTORS["encrypt"], ids=lambda v: v["id"])
def test_encrypt_for_channel_serializes_the_payload_as_the_vector_does(vector: dict) -> None:
    # The vector's plaintext is the JSON serialization of the payload, so feeding the
    # parsed payload back through must reproduce the same bytes — this is what pins
    # Python's json.dumps separators to the compact form the other SDKs emit.
    envelope = encrypt_for_channel(
        vector["channel"],
        json.loads(vector["plaintext"]),
        decode_master_key(vector["master_key"]),
        nonce=_b64(vector["nonce"]),
    )
    assert envelope == {"nonce": vector["nonce"], "ciphertext": vector["ciphertext"]}


@pytest.mark.parametrize("vector", VECTORS["decrypt"], ids=lambda v: v["id"])
def test_open_box_honors_the_vector_verdict(vector: dict) -> None:
    key = derive_shared_secret(vector["channel"], decode_master_key(vector["master_key"]))
    plain = open_box(_b64(vector["ciphertext"]), _b64(vector["nonce"]), key)
    if vector["result"] == "valid":
        assert plain is not None
        assert plain.decode() == vector["plaintext"]
    else:
        assert plain is None


@pytest.mark.parametrize("vector", VECTORS["authorize_channel"], ids=lambda v: v["id"])
def test_authorize_channel_matches_the_vector(vector: dict) -> None:
    bird = Bird(
        api_key="bk_eu1_secret",
        realtime_key=vector["key"],
        realtime_secret=vector["secret"],
        realtime_encryption_master_key=vector.get("master_key"),
    )
    out = bird.realtime.authorize_channel(
        connection_id=vector["connection_id"],
        channel_name=vector["channel"],
        member_data=vector.get("member_data"),
    )
    assert out["auth"] == vector["auth"]
    assert out.get("member_data") == vector.get("member_data")
    assert out.get("shared_secret") == vector.get("shared_secret")


def test_authorize_channel_needs_the_app_credentials() -> None:
    bird = Bird(api_key="bk_eu1_secret")
    with pytest.raises(BirdError, match="realtime_key"):
        bird.realtime.authorize_channel(connection_id="1.1", channel_name="private-room")


def test_authorize_channel_needs_the_master_key_for_an_encrypted_channel() -> None:
    with pytest.raises(BirdError, match="realtime_encryption_master_key"):
        client(master_key=None).realtime.authorize_channel(
            connection_id="1.1", channel_name=CHANNEL
        )


def test_a_master_key_of_the_wrong_length_is_rejected_naming_the_config() -> None:
    with pytest.raises(BirdError, match="must be 32 bytes"):
        client(master_key=base64.b64encode(b"too short").decode()).realtime.authorize_channel(
            connection_id="1.1", channel_name=CHANNEL
        )


@respx.mock
def test_publish_seals_the_payload_before_it_leaves_the_process() -> None:
    route = respx.post(f"{APP_BASE}/events").mock(return_value=httpx.Response(200, json={}))
    client().realtime.publish(
        APP, event="order.updated", channels=[CHANNEL], data={"id": 42, "status": "shipped"}
    )

    raw = route.calls.last.request.content
    assert b"shipped" not in raw
    body = json.loads(raw)
    assert body["channels"] == [CHANNEL]
    assert sorted(body["data"]) == ["ciphertext", "nonce"]
    assert _opened(body["data"]) == {"id": 42, "status": "shipped"}


@respx.mock
def test_publish_leaves_a_plain_channel_untouched() -> None:
    route = respx.post(f"{APP_BASE}/events").mock(return_value=httpx.Response(200, json={}))
    client().realtime.publish(APP, event="order.updated", channels=["orders"], data={"id": 42})
    assert json.loads(route.calls.last.request.content)["data"] == {"id": 42}


@respx.mock
def test_a_multi_channel_publish_naming_an_encrypted_channel_is_refused() -> None:
    route = respx.post(f"{APP_BASE}/events").mock(return_value=httpx.Response(200, json={}))
    with pytest.raises(BirdError, match="exactly that one channel"):
        client().realtime.publish(APP, event="e", channels=[CHANNEL, "orders"], data={})
    assert route.call_count == 0


@respx.mock
def test_an_encrypted_publish_without_a_master_key_is_refused() -> None:
    route = respx.post(f"{APP_BASE}/events").mock(return_value=httpx.Response(200, json={}))
    with pytest.raises(BirdError, match="realtime_encryption_master_key"):
        client(master_key=None).realtime.publish(APP, event="e", channels=[CHANNEL], data={})
    assert route.call_count == 0


@respx.mock
def test_publish_batch_seals_only_its_encrypted_items() -> None:
    route = respx.post(f"{APP_BASE}/batch-events").mock(return_value=httpx.Response(200, json={}))
    client().realtime.publish_batch(
        APP,
        events=[
            {"event": "e1", "channel": "orders", "data": {"plain": True}},
            {"event": "e2", "channel": CHANNEL, "data": {"secret": 1}},
        ],
    )

    events = json.loads(route.calls.last.request.content)["events"]
    assert events[0]["data"] == {"plain": True}
    assert events[1]["channel"] == CHANNEL
    assert _opened(events[1]["data"]) == {"secret": 1}


@respx.mock
async def test_the_async_client_seals_the_same_way() -> None:
    route = respx.post(f"{APP_BASE}/events").mock(return_value=httpx.Response(200, json={}))
    async with AsyncBird(
        api_key="bk_eu1_secret",
        realtime_key="rk_test",
        realtime_secret="rs_test",
        realtime_encryption_master_key=MASTER,
    ) as client_:
        await client_.realtime.publish(APP, event="e", channels=[CHANNEL], data={"id": 7})
        authorization = client_.realtime.authorize_channel(
            connection_id="1.1", channel_name=CHANNEL
        )
        assert authorization.get("shared_secret")

    assert _opened(json.loads(route.calls.last.request.content)["data"]) == {"id": 7}


def test_with_options_carries_the_encryption_master_key() -> None:
    derived = client().with_options(max_retries=0)
    out = derived.realtime.authorize_channel(connection_id="1.1", channel_name=CHANNEL)
    assert out.get("shared_secret") == VECTORS["derive_shared_secret"][0]["shared_secret"]


def test_sealing_without_pynacl_names_the_extra_to_install(monkeypatch: pytest.MonkeyPatch) -> None:
    # Authorizing an encrypted channel is pure hashlib and must keep working; only
    # sealing needs the cipher, and its failure has to name the extra.
    real_import = builtins.__import__

    def no_nacl(name: str, *args: object, **kwargs: object) -> object:
        if name.startswith("nacl"):
            raise ImportError("No module named 'nacl'")
        return real_import(name, *args, **kwargs)  # type: ignore[arg-type]

    monkeypatch.setattr(builtins, "__import__", no_nacl)

    assert client().realtime.authorize_channel(connection_id="1.1", channel_name=CHANNEL)
    with pytest.raises(BirdError, match="realtime-encryption"):
        client().realtime.publish(APP, event="e", channels=[CHANNEL], data={})
